std::future<int> submit(std::function<int()> fn) {
    std::packaged_task<int()> task(std::move(fn));
    std::future<int> fut = task.get_future();      // the caller keeps this end
    queue.push(std::move(task));                   // move-only: one task, one result
    return fut;
}

void worker_loop() {                               // on each pool thread
    while (std::optional<std::packaged_task<int()>> task = queue.pop())
        (*task)();                                 // stores the value or the exception
}

